def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])

    # Identify the three adjacent nonzero cells along the top.
    start = next(c for c in range(w - 2)
                 if all(grid[0][c + k] != 0 for k in range(3)))
    colors = [grid[0][start + k] for k in range(3)]

    for i, color in enumerate(colors):
        col = start + i
        marker = None
        for r in range(1, h):
            for c in range(w):
                if grid[r][c] == color:
                    marker = (r, c)
                    break
            if marker is not None:
                break

        if i == 1:
            # The center color forms a full vertical line.
            for r in range(h):
                g[r][col] = color
        elif marker is not None:
            r, c = marker
            # Connect the top cell vertically to the marker's row.
            for y in range(r + 1):
                g[y][col] = color
            # From the marker, continue horizontally outward, away from
            # the three-color pattern.
            if i == 0:
                for x in range(0, col):
                    g[r][x] = color
            else:
                for x in range(col + 1, w):
                    g[r][x] = color

    return g
